DROP TABLE IF EXISTS application_codes_csds;

CREATE TABLE IF NOT EXISTS application_codes_csds
(
    ac_id numeric NOT NULL,
    application_code character varying(10) COLLATE pg_catalog."default" NOT NULL,
    application_code_title character varying(500) COLLATE pg_catalog."default" NOT NULL,
    application_code_wording text COLLATE pg_catalog."default" NOT NULL,
    application_legislation text COLLATE pg_catalog."default",
    fee_due character(1) COLLATE pg_catalog."default" NOT NULL,
    application_code_respondent character(1) COLLATE pg_catalog."default" NOT NULL,
    ac_destination_email_address_1 character varying(253) COLLATE pg_catalog."default",
    ac_destination_email_address_2 character varying(253) COLLATE pg_catalog."default",
    application_code_start_date date NOT NULL,
    application_code_end_date date,
    bulk_respondent_allowed character(1) COLLATE pg_catalog."default" NOT NULL,
    version numeric NOT NULL,
    changed_by numeric NOT NULL,
    changed_date timestamp without time zone NOT NULL,
    user_name character varying(250) COLLATE pg_catalog."default",
    ac_fee_reference character varying(12) COLLATE pg_catalog."default",
    CONSTRAINT application_codes_pk PRIMARY KEY (ac_id)
);

