DROP TABLE IF EXISTS resolution_codes_csds;

CREATE TABLE IF NOT EXISTS resolution_codes_csds
(
    rc_id numeric NOT NULL,
    resolution_code character varying(10) COLLATE pg_catalog."default" NOT NULL,
    resolution_code_title character varying(500) COLLATE pg_catalog."default" NOT NULL,
    resolution_code_wording text COLLATE pg_catalog."default" NOT NULL,
    resolution_legislation text COLLATE pg_catalog."default",
    rc_destination_email_address_1 character varying(253) COLLATE pg_catalog."default",
    rc_destination_email_address_2 character varying(253) COLLATE pg_catalog."default",
    resolution_code_start_date date NOT NULL,
    resolution_code_end_date date,
    version numeric NOT NULL,
    changed_by numeric NOT NULL,
    changed_date timestamp without time zone NOT NULL,
    user_name character varying(250) COLLATE pg_catalog."default",
    CONSTRAINT resolution_codes_pk PRIMARY KEY (rc_id)
);

